// src/capture-status.ts
import { createHash, randomUUID } from "crypto";
import { join, resolve } from "path";
import {
  mkdirSync,
  readFileSync,
  readdirSync,
  realpathSync,
  renameSync,
  rmSync,
  statSync,
  writeFileSync
} from "fs";
import { homedir } from "os";
function cacheDirectory(env = process.env, home = homedir()) {
  return join(env["XDG_CACHE_HOME"]?.trim() || join(home, ".cache"), "opencode-claude-mem");
}
function statusKey(directory) {
  let resolved = resolve(directory);
  try {
    resolved = realpathSync(directory);
  } catch {}
  return createHash("sha256").update(resolved).digest("hex").slice(0, 16);
}
function isAlive(pid) {
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    return error.code === "EPERM";
  }
}
function parseStatus(file) {
  try {
    const parsed = JSON.parse(readFileSync(file, "utf8"));
    if (typeof parsed !== "object" || parsed === null) {
      return null;
    }
    const { state, message, pid } = parsed;
    return (state === "ok" || state === "problem") && typeof message === "string" && typeof pid === "number" && Number.isInteger(pid) && pid > 0 ? { state, message, pid } : null;
  } catch {
    return null;
  }
}
function readCaptureStatus(directory, dir = cacheDirectory()) {
  const folder = join(dir, "status");
  const prefix = `${statusKey(directory)}.`;
  let names = [];
  try {
    names = readdirSync(folder).filter((name) => name.startsWith(prefix) && name.endsWith(".json"));
  } catch {
    return null;
  }
  let best = null;
  for (const name of names) {
    const file = join(folder, name);
    const parsed = parseStatus(file);
    if (!parsed || !isAlive(parsed.pid)) {
      rmSync(file, { force: true });
    } else {
      const own = parsed.pid === process.pid;
      const at = statSync(file, { throwIfNoEntry: false })?.mtimeMs ?? 0;
      if (!best || own && !best.own || own === best.own && at > best.at) {
        best = { status: { state: parsed.state, message: parsed.message }, own, at };
      }
    }
  }
  return best?.status ?? null;
}

// src/worker-client.ts
import { existsSync, readFileSync as readFileSync2 } from "fs";
import { join as join2, resolve as resolve2, win32 } from "path";
import { createHash as createHash2 } from "crypto";
import { homedir as homedir2 } from "os";
var DEFAULT_WORKER_HOST = "127.0.0.1";
var WORKER_PORT_BASE = 37700;
var TOKEN_HEADER = "x-claude-mem-token";
var PROJECT_COUNTS_SQL = `SELECT
  (SELECT COUNT(*) FROM observations
    WHERE project = ?1 COLLATE NOCASE OR merged_into_project = ?1 COLLATE NOCASE) AS observations,
  (SELECT COUNT(*) FROM session_summaries
    WHERE project = ?1 COLLATE NOCASE OR merged_into_project = ?1 COLLATE NOCASE) AS summaries,
  (SELECT COUNT(*) FROM sdk_sessions WHERE project = ?1 COLLATE NOCASE) AS sessions`;
function isRecord(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
function readString(value) {
  if (typeof value !== "string") {
    return null;
  }
  const trimmed = value.trim();
  return trimmed || null;
}
function readPort(value) {
  const text = readString(value);
  if (!text || !/^\d+$/.test(text)) {
    return null;
  }
  const port = Number(text);
  return Number.isInteger(port) && port >= 1 && port <= 65535 ? port : null;
}
function parseSettings(rawSettings) {
  if (!rawSettings) {
    return {};
  }
  try {
    const parsed = JSON.parse(rawSettings.replace(/^\uFEFF/, ""));
    if (!isRecord(parsed)) {
      return {};
    }
    const nested = parsed["env"];
    const source = isRecord(nested) && Object.keys(nested).some((key) => key.startsWith("CLAUDE_MEM_")) ? nested : parsed;
    return Object.fromEntries(Object.entries(source).map(([key, value]) => [
      key,
      typeof value === "number" || typeof value === "boolean" ? String(value) : value
    ]));
  } catch {
    return {};
  }
}
function dataDirectory(env, home) {
  const dir = readString(env["CLAUDE_MEM_DATA_DIR"]) ?? join2(home, ".claude-mem");
  return dir.replace(/^~(?=$|[\\/])/, home);
}
function defaultWorkerPort(dataDir, platform = process.platform, uid = typeof process.getuid === "function" ? process.getuid() : null) {
  if (uid !== null) {
    return WORKER_PORT_BASE + (uid % 100 + 100) % 100;
  }
  const normalized = platform === "win32" ? win32.resolve(dataDir).toLowerCase() : resolve2(dataDir);
  const digest = createHash2("sha256").update(normalized, "utf8").digest();
  return WORKER_PORT_BASE + digest.readUInt32BE(0) % 100;
}
function parseWorkerEndpoint(env, rawSettings, fallbackPort = defaultWorkerPort(dataDirectory(env, homedir2()))) {
  const settings = parseSettings(rawSettings);
  const configured = readString(env["CLAUDE_MEM_WORKER_HOST"]) ?? readString(settings["CLAUDE_MEM_WORKER_HOST"]) ?? DEFAULT_WORKER_HOST;
  const host = configured === "localhost" ? DEFAULT_WORKER_HOST : configured;
  const port = readPort(env["CLAUDE_MEM_WORKER_PORT"]) ?? readPort(settings["CLAUDE_MEM_WORKER_PORT"]) ?? fallbackPort;
  return { host, port };
}
function isLoopbackHost(host) {
  const name = host.toLowerCase().replace(/^\[|\]$/g, "");
  return name === "localhost" || name.endsWith(".localhost") || name === "::1" || /^127(?:\.\d{1,3}){1,3}$/.test(name);
}
function workerUrl(endpoint) {
  const host = endpoint.host.includes(":") && !endpoint.host.startsWith("[") ? `[${endpoint.host}]` : endpoint.host;
  return `http://${host}:${endpoint.port}`;
}
function tokenHeaders(baseUrl, rawSettings) {
  const token = readString(parseSettings(rawSettings)["CLAUDE_MEM_LOCAL_API_TOKEN"]);
  try {
    return token && isLoopbackHost(new URL(baseUrl).hostname) ? { [TOKEN_HEADER]: token } : {};
  } catch {
    return {};
  }
}
function resolveDatabasePath(env, rawSettings, home) {
  if (!isLoopbackHost(parseWorkerEndpoint(env, rawSettings).host)) {
    return null;
  }
  const settings = parseSettings(rawSettings);
  const dir = readString(env["CLAUDE_MEM_DATA_DIR"]) ?? readString(settings["CLAUDE_MEM_DATA_DIR"]) ?? join2(home, ".claude-mem");
  return join2(dir.replace(/^~(?=$|[\\/])/, home), "claude-mem.db");
}
function readCount(value) {
  return typeof value === "number" && Number.isInteger(value) && value >= 0 ? value : null;
}
async function readProjectCounts(path, project) {
  if (!existsSync(path)) {
    return null;
  }
  try {
    const { Database } = await import("bun:sqlite");
    const db = new Database(path, { readonly: true });
    try {
      const row = db.query(PROJECT_COUNTS_SQL).get(project);
      if (!isRecord(row)) {
        return null;
      }
      const observations = readCount(row["observations"]);
      const summaries = readCount(row["summaries"]);
      const sessions = readCount(row["sessions"]);
      return observations === null || summaries === null || sessions === null ? null : { observations, summaries, sessions };
    } finally {
      db.close();
    }
  } catch {
    return null;
  }
}
function readEpoch(item) {
  const at = item["created_at_epoch"];
  return typeof at === "number" && Number.isFinite(at) ? at : null;
}
function readSettingsRaw() {
  try {
    return readFileSync2(join2(dataDirectory(process.env, homedir2()), "settings.json"), "utf8");
  } catch {
    return null;
  }
}
function readWorkerSetting(key) {
  return readString(process.env[key]) ?? readString(parseSettings(readSettingsRaw())[key]);
}
function getWorkerEndpoint() {
  return parseWorkerEndpoint(process.env, readSettingsRaw());
}
function getWorkerBaseUrl() {
  return workerUrl(getWorkerEndpoint());
}
function workerHeaders(baseUrl = getWorkerBaseUrl()) {
  return tokenHeaders(baseUrl, readSettingsRaw());
}

class WorkerClient {
  static BASE_URL = getWorkerBaseUrl();
  static SUPPORTED = !readWorkerSetting("CLAUDE_MEM_WORKER_URL");
  static DATABASE_PATH = resolveDatabasePath(process.env, readSettingsRaw(), homedir2());
  static get(path) {
    if (!this.SUPPORTED) {
      return Promise.reject(new Error("CLAUDE_MEM_WORKER_URL is not supported"));
    }
    return fetch(`${this.BASE_URL}${path}`, {
      headers: workerHeaders(this.BASE_URL),
      redirect: "error"
    });
  }
  static getProjectCounts(project) {
    return this.DATABASE_PATH && this.SUPPORTED ? readProjectCounts(this.DATABASE_PATH, project) : Promise.resolve(null);
  }
  static async getStats() {
    try {
      const [statsRes, processingRes] = await Promise.all([
        this.get(`/api/stats`),
        this.get(`/api/processing-status`)
      ]);
      if (!statsRes.ok) {
        return null;
      }
      const stats = await statsRes.json();
      const processing = processingRes.ok ? await processingRes.json() : undefined;
      return { database: stats.database, processing };
    } catch {
      return null;
    }
  }
  static async getRecentSummaries(project, limit) {
    try {
      const params = new URLSearchParams({ project, limit: String(limit) });
      const response = await this.get(`/api/summaries?${params.toString()}`);
      if (!response.ok) {
        return [];
      }
      const payload = await response.json();
      if (!Array.isArray(payload.items)) {
        return [];
      }
      return payload.items.flatMap((item) => {
        if (!isRecord(item) || typeof item["id"] !== "number") {
          return [];
        }
        const request = typeof item["request"] === "string" ? item["request"].trim() : "";
        return request ? [{ id: item["id"], request, at: readEpoch(item) }] : [];
      });
    } catch {
      return [];
    }
  }
  static async getRecentObservations(project, limit) {
    try {
      const params = new URLSearchParams({ project, limit: String(limit) });
      const response = await this.get(`/api/observations?${params.toString()}`);
      if (!response.ok) {
        return [];
      }
      const payload = await response.json();
      if (!Array.isArray(payload.items)) {
        return [];
      }
      return payload.items.flatMap((item) => {
        if (!isRecord(item) || typeof item["id"] !== "number") {
          return [];
        }
        const title = typeof item["title"] === "string" ? item["title"].trim() : "";
        const type = typeof item["type"] === "string" ? item["type"] : "";
        return title ? [{ id: item["id"], type, title, at: readEpoch(item) }] : [];
      });
    } catch {
      return [];
    }
  }
  static async getDetail(kind, id) {
    try {
      const path = kind === "observation" ? "observation" : "session";
      const response = await this.get(`/api/${path}/${id}`);
      if (!response.ok) {
        return null;
      }
      const payload = await response.json();
      return isRecord(payload) ? payload : null;
    } catch {
      return null;
    }
  }
}

// src/sidebar-model.ts
var POLL_INTERVAL_MS = 5000;
var RECENT_SUMMARIES = 3;
var RECENT_OBSERVATIONS = 3;
var OBSERVATION_TYPE_ICONS = {
  bugfix: "\u25CF",
  feature: "\u25C6",
  refactor: "\u21BB",
  change: "\u2713",
  discovery: "\u25CB",
  decision: "\u2696",
  security_alert: "\u26A0",
  security_note: "\u26B7"
};
function box(props, children) {
  return { kind: "box", props, children };
}
function text(props, value) {
  return { kind: "text", props, text: value };
}
var HTML_ENTITIES = {
  "&lt;": "<",
  "&gt;": ">",
  "&quot;": '"',
  "&#39;": "'",
  "&amp;": "&"
};
function decodeEntities(value) {
  return value.replace(/&(?:lt|gt|quot|#39|amp);/g, (entity) => HTML_ENTITIES[entity] ?? entity);
}
function stripProjectName(value, project) {
  const decoded = decodeEntities(value);
  const name = project.trim();
  if (!name) {
    return decoded;
  }
  const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, String.raw`\$&`);
  const stripped = decoded.replace(new RegExp(`(?<![\\w.@-])(?:[\\w.@-]+/)?${escaped}(?![\\w.-])`, "giu"), " ").replaceAll(/\s{2,}/g, " ").replaceAll(/\s+([\uFF0C\u3002\u3001\uFF1B\uFF1A,.:;])/g, "$1").replace(/^[\s:\uFF1A,\uFF0C\u3001;\uFF1B\u00B7|\u2013\u2014-]+/u, "").trim();
  return stripped || decoded;
}
function formatAge(at, now) {
  if (at === null || !Number.isFinite(at)) {
    return "";
  }
  const minutes = Math.floor(Math.max(0, now - at) / 60000);
  if (minutes < 1) {
    return "just now";
  }
  if (minutes < 60) {
    return `${minutes}m ago`;
  }
  const hours = Math.floor(minutes / 60);
  if (hours < 24) {
    return `${hours}h ago`;
  }
  const days = Math.floor(hours / 24);
  if (days < 7) {
    return `${days}d ago`;
  }
  const date = new Date(at);
  return `${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}
function formatCount(value) {
  if (value === null) {
    return "-";
  }
  return value >= 1e4 ? `${(value / 1000).toFixed(1)}k` : String(value);
}
function summaryLine(view) {
  if (!view.healthy) {
    return { label: "(offline)", tone: "err" };
  }
  if (view.capture?.state === "problem") {
    return { label: "(capture off)", tone: "err" };
  }
  if (view.isProcessing || (view.queueDepth ?? 0) > 0) {
    return { label: `(queue ${view.queueDepth ?? 0})`, tone: "warn" };
  }
  return { label: `(online, ${formatCount(view.observations)} obs)`, tone: "ok" };
}
function toneColor(tone, theme) {
  if (tone === "err") {
    return theme.error;
  }
  return tone === "warn" ? theme.warning : theme.textMuted;
}
function label(color, value) {
  return text({ fg: color, wrapMode: "none", truncate: true }, value);
}
function bulletRow(icon, iconColor, value, theme, labelColor = theme.text) {
  return box({ flexDirection: "row", gap: 1 }, [
    text({ fg: iconColor, flexShrink: 0 }, icon),
    label(labelColor, decodeEntities(value))
  ]);
}
function leftClick(action) {
  let pressed = false;
  return {
    onMouseDown(event) {
      pressed = event.button === 0;
    },
    onMouseDrag() {
      pressed = false;
    },
    onMouseOut() {
      pressed = false;
    },
